from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import permissions, status
from silk.models import Request as SilkRequest

class SilkRecordedPayloadDetailView(APIView):
    permission_classes = [permissions.IsAuthenticated]

    def get(self, request, request_id):
        # Scope lookup strictly to profiling traces initiated by the authenticated user
        silk_record = SilkRequest.objects.filter(
            id=request_id,
            user_id=request.user.id
        ).first()
        if not silk_record:
            return Response({"error": "Recorded trace not found or access denied"}, status=status.HTTP_404_NOT_FOUND)

        return Response({
            "path": silk_record.path,
            "headers": silk_record.headers,
            "raw_body": silk_record.raw_body,
            "query_params": silk_record.query_params
        }, status=status.HTTP_200_OK)
